import json
n=28
out=[[0]*n for _ in range(n)]
for r in range(n):
    if r%5==4: out[r]=[8]*n
    else:
        for c in range(n):
            if c%5==4: out[r][c]=8
# panel rows / cols: 2 in rows 1,3; 3 in col 2; intersection 6
for pr in range(5):
    for pc in range(5):
        color=6 if pr in (1,3) and pc==2 else (2 if pr in (1,3) else (3 if pc==2 else 0))
        if color:
            for rr in range(pr*5,pr*5+4):
                for cc in range(pc*5,pc*5+4):
                    out[rr][cc]=color
print(json.dumps(out))

